+/// Roll up balances to the first `depth` levels of the account name.
+///
+/// For example, at `depth = 2`, `expenses:food:groceries` counts towards `expenses:food`.
+/// Shallower accounts keep their name.
+///
+/// Returned values are sorted by account name and omit zero roll-ups.
+///
+/// # Panics
+/// Panics if `depth == 0`.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth must be non-zero");
+
+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for (account, balance) in ledger.balances() {
+        let parts: Vec<&str> = account.split(':').collect();
+        let rolled = if parts.len() <= depth {
+            account
+        } else {
+            parts[..depth].join(":")
+        };
+        *totals.entry(rolled).or_default() += balance;
+    }
+
+    totals
+        .into_iter()
+        .filter(|(_, a)| !a.is_zero())
+        .collect()
